// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { Btn, DemoStage, highlight, PanelChrome, type Build } from '@/app/demos/stage'

import { BROKEN_ERROR, BROKEN_INDEX, CAPTIONS, PAIRS, VALID_BADGE } from './script'

const ROW = 20
const INDENT = 14

/** [first YAML row, row count] for each nested block, after the JSON braces collapse. */
const GUIDES = (() => {
  const depths = PAIRS.filter(([, yaml]) => yaml !== null).map(([, , depth]) => depth)
  const blocks: [number, number][] = []
  depths.forEach((depth, row) => {
    if (depth === 0) return
    const last = blocks[blocks.length - 1]
    if (last && last[0] + last[1] === row) last[1] += 1
    else blocks.push([row, 1])
  })
  return blocks
})()

function yamlTokens(line: string) {
  const [key, ...rest] = line.split(':')
  const value = rest.join(':')
  return (
    <>
      <span className="text-[#93c5fd]">{key}</span>
      <span className="text-muted">:</span>
      <span className="text-amber">{value}</span>
    </>
  )
}

const build: Build = ({ tl, q, qa, step, final, move, click, scramble, wait, cursorOut }) => {
  step(0)
  tl.fromTo(
    qa('json'),
    { opacity: 0, x: -8 },
    { opacity: 1, x: 0, duration: 0.3, stagger: 0.04 },
    0.3,
  )

  step(1, '+=0.4')
  move('convert')
  click('convert')
  tl.to(
    qa('gone'),
    { height: 0, opacity: 0, duration: 0.45, ease: 'power3.inOut', stagger: 0.03 },
    '<0.1',
  )
  tl.to(
    qa('json-kept'),
    { rotateX: 90, opacity: 0, duration: 0.25, stagger: 0.04, ease: 'power2.in' },
    '<',
  )
  tl.fromTo(
    qa('yaml'),
    { rotateX: -90, opacity: 0 },
    { rotateX: 0, opacity: 1, duration: 0.4, stagger: 0.04, ease: 'back.out(2)' },
    '<0.2',
  )
  tl.fromTo(
    qa('guide'),
    { scaleY: 0 },
    { scaleY: 1, duration: 0.4, stagger: 0.1, ease: 'expo.out' },
    '-=0.2',
  )
  scramble('mode', 'YAML', { at: '<', duration: 0.4 })

  step(2, '+=0.5')
  move('broken', { ax: 0.1 })
  click('broken')
  tl.to(q('broken'), { x: 7, color: '#fb7185', duration: 0.25 }, '<')
  tl.to(
    q('status'),
    { backgroundColor: 'rgba(251,113,133,0.14)', color: '#fb7185', duration: 0.2 },
    '<0.2',
  )
  scramble('status-text', BROKEN_ERROR, { at: '<', duration: 0.6 })

  step(3, '+=0.6')
  tl.to(q('broken'), { x: 0, color: '#d4d4de', duration: 0.3 })
  move('validate')
  click('validate')
  tl.to(
    q('status'),
    { backgroundColor: 'rgba(52,211,153,0.14)', color: '#34d399', duration: 0.2 },
    '<',
  )
  scramble('status-text', VALID_BADGE, { at: '<', duration: 0.5 })
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="YAML Toolkit converting JSON to YAML, catching a bad indent and validating"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome
        aside={
          <span
            data-d="mode"
            className="rounded-full border border-line-strong px-2.5 py-1 font-mono text-[10px] text-[var(--accent)]"
          >
            JSON
          </span>
        }
      >
        <div className="flex h-full flex-col gap-2.5">
          <div className="relative min-h-0 flex-1 overflow-hidden rounded-xl border border-line bg-canvas/80 p-3 font-mono text-[11px] [perspective:500px]">
            {GUIDES.map(([row, rows]) => (
              <span
                key={row}
                data-d="guide"
                className="absolute w-px origin-top bg-[var(--accent)]/50"
                style={{ left: 16, top: 12 + row * ROW + 2, height: rows * ROW - 4 }}
              />
            ))}
            {PAIRS.map(([json, yaml, depth], index) => (
              <div
                key={index}
                data-d={yaml === null ? 'gone' : undefined}
                className="grid overflow-hidden"
                style={{ height: ROW }}
              >
                <p
                  data-d={yaml === null ? 'json' : 'json json-kept'}
                  className="whitespace-pre leading-[20px] [grid-area:1/1]"
                >
                  {highlight(json)}
                </p>
                {yaml !== null ? (
                  <p
                    data-d={index === BROKEN_INDEX ? 'yaml broken' : 'yaml'}
                    className="whitespace-pre leading-[20px] text-ink-soft opacity-0 [grid-area:1/1]"
                    style={{ paddingLeft: depth * INDENT }}
                  >
                    {yamlTokens(yaml)}
                  </p>
                ) : null}
              </div>
            ))}
          </div>
          <p
            data-d="status"
            className="rounded-lg bg-ink/[0.04] px-3 py-1.5 font-mono text-[10.5px] text-muted"
          >
            <span data-d="status-text">Not validated</span>
          </p>
          <div className="flex gap-2">
            <Btn d="convert" primary>
              JSON → YAML
            </Btn>
            <Btn d="validate">Validate</Btn>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
